/**
 * A value as text: empty when absent.
 * @param {unknown} value
 * @returns {string}
 */
function text(value) {
  return value == null ? '' : String(value);
}

/**
 * True when a value is absent, an empty text or an empty list.
 * @param {unknown} value
 * @returns {boolean}
 */
function empty(value) {
  return value == null || value === '' || (Array.isArray(value) && value.length === 0);
}

/**
 * A value as the number it states, or NaN when it states none.
 * @param {unknown} value
 * @returns {number}
 */
function numeric(value) {
  if (typeof value === 'number') return value;
  if (typeof value !== 'string') return Number.NaN;
  const text = value.trim();
  return /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(text) ? Number(text) : Number.NaN;
}

/**
 * A text as an address segment: Unicode NFKD, combining marks removed, lower case, every run of
 * characters other than a-z and 0-9 replaced by `-`, `-` trimmed at both ends, cut to 80
 * characters, a trailing `-` trimmed again.
 * @param {string} value
 * @returns {string}
 */
export function slug(value) {
  return value
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80)
    .replace(/-+$/, '');
}

