/** Form `form-accept-invitation` of screen `screen-sign-in`: calls `accept-owner-invitation`. */
const formAcceptInvitation = {
  /** @param {any} scope */
  initial(scope) {
    return this.derive({ password: '' }, [], scope ?? {});
  },
  options: {

  },
  /**
   * @param {Record<string, any>} values
   * @param {string[]} _edited
   * @param {any} _context
   */
  derive(values, _edited, _context) {
    const next = { ...values };
    return next;
  },
  /** @param {Record<string, any>} values */
  validate(values) {
    /** @type {Record<string, string>} */
    const errors = {};
    if (errors.password === undefined && (!new RegExp('^(?:[\\p{White_Space}\\P{White_Space}]{10,})$', 'u').test(String(values.password)))) errors.password = 'Choose a password of at least 10 characters.';
    if (errors.password === undefined && (new TextEncoder().encode(String(values.password)).length > 256)) errors.password = 'Choose a password of at most 256 bytes.';
    return errors;
  },
  /**
   * @param {Record<string, any>} values
   * @param {any} scope
   */
  inputs(values, scope) {
    return { password: values.password, challenge: scope.local?.invitation_challenge, token: scope.local?.invitation_token };
  },
  /** @param {Record<string, any>} raw */
  submitted(raw) {
    return { password: String(raw.password ?? '') };
  },
  /**
   * @param {any} _scope
   * @returns {{ contract: string, inputs: Record<string, any> } | null}
   */
  then(_scope) {
    return null;
  },
  /** @param {any} scope */
  succeeded(scope) {
    return { navigate: hrefFor('screen-sign-in', {}), toast: 'Your password is set. Sign in as ' + text(scope.response?.login) + '.', view: null };
  },
};

